-- Oracle 12c+; destructive reset. Dedicated practice schema ONLY.
SET DEFINE OFF
BEGIN
 FOR T IN (SELECT TABLE_NAME FROM USER_TABLES WHERE TABLE_NAME IN ('WIDE_COUNTS','ENROLL','ORDERS','PLAYER','COURSE','STUDENT','TEAM','DEPT','CUSTOMER','DDL_LAB','FK_LAB')) LOOP
   EXECUTE IMMEDIATE 'DROP TABLE '||T.TABLE_NAME||' CASCADE CONSTRAINTS PURGE';
 END LOOP;
END;
/
CREATE TABLE TEAM (TEAM_ID VARCHAR2(4) PRIMARY KEY, TEAM_NAME VARCHAR2(30) NOT NULL);
CREATE TABLE DEPT (DEPT_ID NUMBER(5) PRIMARY KEY, DEPT_NAME VARCHAR2(30) NOT NULL);
CREATE TABLE PLAYER (PLAYER_ID NUMBER(5) PRIMARY KEY, TEAM_ID VARCHAR2(4) NOT NULL REFERENCES TEAM(TEAM_ID), PLAYER_NAME VARCHAR2(30) NOT NULL, POSITION VARCHAR2(2), SALARY NUMBER(10) NOT NULL, HIRE_DATE DATE NOT NULL, MANAGER_ID NUMBER(5), BONUS NUMBER(10), ACTIVE_YN CHAR(1) NOT NULL, DEPT_ID NUMBER(5) REFERENCES DEPT(DEPT_ID), CONSTRAINT FK_PLAYER_MANAGER FOREIGN KEY (MANAGER_ID) REFERENCES PLAYER(PLAYER_ID), CONSTRAINT CK_PLAYER_PAY CHECK (SALARY>=0));
CREATE TABLE CUSTOMER (CUSTOMER_ID NUMBER(5) PRIMARY KEY, CUSTOMER_NAME VARCHAR2(30) NOT NULL, REGION VARCHAR2(20));
CREATE TABLE ORDERS (ORDER_ID NUMBER(5) PRIMARY KEY, CUSTOMER_ID NUMBER(5) NOT NULL REFERENCES CUSTOMER(CUSTOMER_ID), ORDER_DATE DATE NOT NULL, AMOUNT NUMBER(10) NOT NULL, STATUS VARCHAR2(12) NOT NULL);
CREATE TABLE STUDENT (STUDENT_ID NUMBER(5) PRIMARY KEY, STUDENT_NAME VARCHAR2(30));
CREATE TABLE COURSE (COURSE_ID NUMBER(5) PRIMARY KEY, COURSE_NAME VARCHAR2(30));
CREATE TABLE ENROLL (ENROLL_ID NUMBER(5) PRIMARY KEY, STUDENT_ID NUMBER(5) NOT NULL REFERENCES STUDENT(STUDENT_ID), COURSE_ID NUMBER(5) NOT NULL REFERENCES COURSE(COURSE_ID), SCORE NUMBER(3), CONSTRAINT UQ_ENROLL UNIQUE (STUDENT_ID,COURSE_ID));
CREATE TABLE WIDE_COUNTS (TEAM_ID VARCHAR2(4) PRIMARY KEY, FW NUMBER(5), MF NUMBER(5));
